import { toProxy, useProxyWatchUpdates, useTranslation } from '@fanfanlo';
import { Box, Chip, Stack, Typography } from '@mui/material';
import { AndroidPermissionsButton } from '@droid/ui';
import { useState } from 'react';
import type { IScript } from '../scripts/IScript';

// 日志前缀
const LOG_PREFIX = '[ScriptPermissionsEditor]';

interface ScriptPermissionsEditorProps {
  scriptData: IScript;
}

/**
 * 脚本权限编辑器组件
 * 编辑 IScript 对象的 permissions 字段
 */
export function ScriptPermissionsEditor({ scriptData }: ScriptPermissionsEditorProps) {
  console.log(`${LOG_PREFIX} 组件初始化`);
  const { t } = useTranslation('homepage/components/script-editor/content/v2/content');

  // 确保 permissions 数组存在
  if (!scriptData.permissions) {
    console.log(`${LOG_PREFIX} scriptData.permissions 为 undefined, 初始化为空数组`);
    scriptData.permissions = [];
  } else {
    console.log(`${LOG_PREFIX} scriptData.permissions 已存在, 长度: ${scriptData.permissions.length}`);
  }

  // 创建 permissionsProps 对象并使用 toProxy 包装
  const [permissionsProps] = useState(() => {
    console.log(`${LOG_PREFIX} 创建 permissionsProps 对象`);
    const props = toProxy({ permissions: scriptData.permissions! });
    console.log(`${LOG_PREFIX} permissionsProps 创建完成`);
    return props;
  });

  // 监听 permissions 数组的变化
  const [permissions] = useProxyWatchUpdates(permissionsProps, 'permissions', permissionsProps.permissions);
  console.log(`${LOG_PREFIX} 当前权限数量: ${permissions.length}`,t('ScriptPermissionsEditor.permissionsCount'));

  return (
    <Box>
      <Stack direction="row" spacing={2} alignItems="center">
        <Typography variant="body2" sx={{ fontWeight: 500 }}>
          {t('ScriptPermissionsEditor.label')}:
        </Typography>
        <Chip
          label={`${permissions.length} ${t('ScriptPermissionsEditor.permissionsCount')}`}
          size="small"
          color={permissions.length > 0 ? 'primary' : 'default'}
        />
        <AndroidPermissionsButton permissionsProps={permissionsProps} />
      </Stack>
    </Box>
  );
}
